PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS businesses (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT DEFAULT '', phone TEXT DEFAULT '', address TEXT DEFAULT '', hours TEXT DEFAULT '', services TEXT DEFAULT '', areas TEXT DEFAULT '', policies TEXT DEFAULT '', payment_methods TEXT DEFAULT '', currency TEXT DEFAULT 'USD', timezone TEXT DEFAULT 'UTC', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS memberships (business_id INTEGER NOT NULL REFERENCES businesses(id), user_id INTEGER NOT NULL REFERENCES users(id), role TEXT NOT NULL CHECK(role IN ('owner','admin','staff')), PRIMARY KEY(business_id,user_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), business_id INTEGER NOT NULL REFERENCES businesses(id), csrf TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), name TEXT NOT NULL, phone TEXT DEFAULT '', email TEXT DEFAULT '', address TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id));
CREATE TABLE IF NOT EXISTS inquiries (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER, title TEXT NOT NULL, source TEXT DEFAULT 'Manual', status TEXT NOT NULL DEFAULT 'New', description TEXT DEFAULT '', follow_up_date TEXT DEFAULT '', assigned_to TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id), FOREIGN KEY(customer_id,business_id) REFERENCES customers(id,business_id));
CREATE TABLE IF NOT EXISTS estimates (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER, inquiry_id INTEGER, title TEXT NOT NULL, amount REAL, description TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Draft', issue_date TEXT DEFAULT '', valid_until TEXT DEFAULT '', follow_up_date TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id), FOREIGN KEY(customer_id,business_id) REFERENCES customers(id,business_id), FOREIGN KEY(inquiry_id,business_id) REFERENCES inquiries(id,business_id));
CREATE TABLE IF NOT EXISTS appointments (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER, title TEXT NOT NULL, date TEXT NOT NULL, time TEXT DEFAULT '', duration TEXT DEFAULT '', location TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Scheduled', assigned_to TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id), FOREIGN KEY(customer_id,business_id) REFERENCES customers(id,business_id));
CREATE TABLE IF NOT EXISTS jobs (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER, inquiry_id INTEGER, estimate_id INTEGER, title TEXT NOT NULL, description TEXT DEFAULT '', date TEXT DEFAULT '', status TEXT NOT NULL DEFAULT 'Not Started', assigned_to TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id), FOREIGN KEY(customer_id,business_id) REFERENCES customers(id,business_id), FOREIGN KEY(inquiry_id,business_id) REFERENCES inquiries(id,business_id), FOREIGN KEY(estimate_id,business_id) REFERENCES estimates(id,business_id));
CREATE TABLE IF NOT EXISTS follow_ups (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), customer_id INTEGER, inquiry_id INTEGER, estimate_id INTEGER, job_id INTEGER, title TEXT NOT NULL, date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'Open', assigned_to TEXT DEFAULT '', notes TEXT DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(id,business_id), FOREIGN KEY(customer_id,business_id) REFERENCES customers(id,business_id), FOREIGN KEY(inquiry_id,business_id) REFERENCES inquiries(id,business_id), FOREIGN KEY(estimate_id,business_id) REFERENCES estimates(id,business_id), FOREIGN KEY(job_id,business_id) REFERENCES jobs(id,business_id));
CREATE TABLE IF NOT EXISTS activity_logs (id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL REFERENCES businesses(id), user_id INTEGER NOT NULL REFERENCES users(id), entity TEXT NOT NULL, entity_id INTEGER NOT NULL, action TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_customer_business ON customers(business_id); CREATE INDEX IF NOT EXISTS idx_inquiry_business ON inquiries(business_id,status); CREATE INDEX IF NOT EXISTS idx_estimate_business ON estimates(business_id,status); CREATE INDEX IF NOT EXISTS idx_appt_business ON appointments(business_id,date); CREATE INDEX IF NOT EXISTS idx_job_business ON jobs(business_id,date); CREATE INDEX IF NOT EXISTS idx_follow_business ON follow_ups(business_id,date,status); CREATE INDEX IF NOT EXISTS idx_activity_business ON activity_logs(business_id,entity,entity_id);
